// AUTO-GENERATED at container start from $VITE_API_URL, $VITE_DEV_MODE and
// $ALLOW_INSECURE_HTTP (siehe scripts/pwa-entrypoint.sh). Diese Datei wird
// beim Build aus public/ kopiert und beim Container-Start ueberschrieben.
//
// Leerer String = gleicher Origin (nginx im PWA-Container proxied /api/*).
window.__CASTEL_API_URL__ = ''

// 'false' = the PWA requires HTTPS (SubtleCrypto + service worker).
// 'true'  = HTTP mode is deliberately allowed (ALLOW_INSECURE_HTTP).
window.__CASTEL_ALLOW_INSECURE_HTTP__ = 'false'
